    const remaining=(s.sourceForces||[]).filter(f=>!used.has(f.id));for(const f of remaining){const side=sideForFaction(s,f.faction,{assign:true});let unresolved=roots[side].find(x=>x.id===`unresolved-${side}`);if(!unresolved){unresolved={id:`unresolved-${side}`,side,name:'Command organization unresolved',commander:'',armyCommander:'',hierarchyLevel:'unresolved',formations:[]};roots[side].push(unresolved);}unresolved.formations.push({source:f,proposal:bySource.get(f.id)||null});}
    const sortNodes=list=>list.sort((a,b)=>{const weight=x=>x.hierarchyLevel==='command'?0:x.hierarchyLevel==='division'?1:x.hierarchyLevel==='brigade'?2:x.hierarchyLevel==='artillery'?3:4;return weight(a)-weight(b)||String(a.name).localeCompare(String(b.name));});for(const k of Object.keys(roots))sortNodes(roots[k]);for(const list of children.values())sortNodes(list);
