    host.innerHTML=SIDE_KEYS.map(side=>{const roots=tree.roots[side]||[],armyCommanders=[...new Set(roots.flatMap(r=>[r.armyCommander]).filter(Boolean))],armyCommander=armyCommanders.length===1?armyCommanders[0]:'';return `<figure class="force-sketch ${side.toLowerCase()}"><figcaption><strong>${safe(sideLabel(scenario(),side))}</strong>${armyCommander?`<span>${safe(armyCommander)}</span>`:'<span>Suggested historical command structure</span>'}</figcaption><div class="force-sketch-trunk"></div><div class="force-sketch-commands force-sketch-tree">${roots.length?roots.map(r=>renderForceCommand(r,tree.children,0)).join(''):'<section class="force-sketch-command unresolved"><div class="force-sketch-command-title"><strong>No source formations extracted</strong><span>Review the source or re-run analysis with the correct supplement.</span></div></section>'}</div></figure>`;}).join('');
