    for(const src of evidence)if(!created.has(src.id)){const side=sideForFaction(s,src.faction,{assign:true}),c=ensureCommand(side,src.name,src.scenarioCommander||src.commander||'',{sourceId:src.id,commandType:src.commandType||src.hierarchyLevel||'command',parentCommandId:null,commandRating:src.commandRating,status:src.status||'',role:src.role||'',notes:src.notes||[]});created.set(src.id,c);}
