  function addProposals(){const proposed=proposedRosterUnits(scenario().sourceForces,ruleset());registerEvidenceSides(scenario(),scenario().sourceForces||[],scenario().sourceCommands||[]);for(const faction of Object.keys(proposed)){const side=sideForFaction(scenario(),faction,{assign:true});for(const p of proposed[faction]){const cmd=ensureCommand(side,p.commandName,p.commander);if(cmd.units.some(u=>u.sourceId===p.sourceId&&u.profile===p.profile&&u.name===p.name))continue;cmd.units.push({id:uid('unit'),sourceId:p.sourceId,name:p.name,profile:p.profile,commander:'',represents:p.represents,traits:p.traits,notes:p.notes,forceRole:p.forceRole||null});}}persist();window.dispatchEvent(new CustomEvent('bax:scenario-changed'));renderForces();}
  function editCommand(faction,id){const c=findCommand(faction,id);if(!c)return;const name=prompt('Command name:',c.name);if(name===null)return;const commander=prompt('Commander:',c.commander||'');if(commander===null)return;const type=prompt('Command type/echelon (Army, Corps, Division, Brigade, Wing, Battle, Artillery, etc.):',c.commandType||c.echelon||'command');if(type===null)return;checkpointForces();c.name=name.trim()||c.name;c.commander=commander.trim();c.commandType=type.trim()||'command';c.echelon=c.commandType;const cr=commandRatingRules();if(cr){const rating=prompt(`Command Rating (${cr.ratingMin??0}–${cr.ratingMax??3}; blank = roll generic rating during playtest):`,c.commandRating==null?'':String(c.commandRating));if(rating!==null)c.commandRating=normalizeCommandRating(rating);}normalizeCommandHierarchy(scenario());persist();window.dispatchEvent(new CustomEvent('bax:scenario-changed'));renderForces();}

